import{_ as a,o as i,c as o,ag as t}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"Local Galleries","description":"Add multiple local gallery locations, configure Docker mounts, and manage source availability in Foldergram.","frontmatter":{"title":"Local Galleries","description":"Add multiple local gallery locations, configure Docker mounts, and manage source availability in Foldergram."},"headers":[],"relativePath":"local-galleries.md","filePath":"local-galleries.md","lastUpdated":1795102221000}'),n={name:"local-galleries.md"};function s(r,e,l,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="local-galleries" tabindex="-1">Local galleries <a class="header-anchor" href="#local-galleries" aria-label="Permalink to &quot;Local galleries&quot;">​</a></h1><p>Foldergram can index photos and videos from multiple folders or drives into one combined browsing experience. Originals stay in their existing locations; adding a source indexes files without copying or moving them.</p><h2 id="your-primary-gallery" tabindex="-1">Your primary gallery <a class="header-anchor" href="#your-primary-gallery" aria-label="Permalink to &quot;Your primary gallery&quot;">​</a></h2><p>Your existing gallery appears automatically in <strong>Settings → Sources</strong> as <strong>Primary gallery</strong>. Its root is set by <code>GALLERY_ROOT</code> or defaults to the <code>gallery</code> folder in <code>DATA_ROOT</code>. The primary path remains managed by environment configuration. Additional locations are stored in SQLite and require no changes to <code>GALLERY_ROOT</code>.</p><h2 id="add-a-local-folder" tabindex="-1">Add a local folder <a class="header-anchor" href="#add-a-local-folder" aria-label="Permalink to &quot;Add a local folder&quot;">​</a></h2><ol><li>Open <strong>Settings → Sources</strong> as an administrator.</li><li>Choose <strong>Add local folder</strong> and enter a name and an absolute server path.</li><li>Choose <strong>Validate path</strong> to check that Foldergram can access the location.</li><li>Choose <strong>Save &amp; Sync</strong> to save the source and start indexing.</li></ol><p>Foldergram indexes media in subfolders and skips media files directly in the selected root. Each enabled source contributes to the combined feeds. Folders with matching names in different sources remain distinct.</p><p>Use <strong>Sync now</strong> on a source to scan that location, or <strong>Scan library</strong> in <strong>Settings → Scan &amp; Library</strong> to scan all enabled local sources. Immich connections have separate sync controls.</p><h2 id="server-paths-and-docker-mounts" tabindex="-1">Server paths and Docker mounts <a class="header-anchor" href="#server-paths-and-docker-mounts" aria-label="Permalink to &quot;Server paths and Docker mounts&quot;">​</a></h2><p>On a native installation, use an absolute path the Foldergram process can read. The path is resolved on the server running Foldergram. Photos on a different computer must first be made available to that server; selecting a folder on the browser&#39;s computer does not expose it to Foldergram.</p><p>In Docker, add a bind mount for each location alongside the existing volumes:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Keep the existing Foldergram volumes and add your locations:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/home/alex/Pictures:/sources/pictures:ro</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/mnt/external/Photos:/sources/external:ro</span></span></code></pre></div><p>The left side is the host path. The right side is the container path to enter in Sources, such as <code>/sources/pictures</code>. After changing mounts, run <code>docker compose up -d</code> to recreate the container with its updated configuration. Docker Desktop users may need to share the host drive or folder with Docker first. Mount external drives before starting or syncing Foldergram.</p><p>Your existing <code>GALLERY_ROOT</code> and database settings can remain in place. Keep SQLite and the derivative directories writable. A read-only photo mount is sufficient for indexing.</p><h2 id="read-only-originals-disabling-and-removal" tabindex="-1">Read-only originals, disabling, and removal <a class="header-anchor" href="#read-only-originals-disabling-and-removal" aria-label="Permalink to &quot;Read-only originals, disabling, and removal&quot;">​</a></h2><p>New locations default to read-only originals. This setting still allows Foldergram metadata edits and moving an indexed post to Trash, while blocking original-file deletion.</p><p>Disabling a source hides its content and shares while retaining its index and saved state. Removing a source clears its index, saved associations, shares, and derivatives. Original files stay on disk.</p><h2 id="disconnected-drives-and-empty-locations" tabindex="-1">Disconnected drives and empty locations <a class="header-anchor" href="#disconnected-drives-and-empty-locations" aria-label="Permalink to &quot;Disconnected drives and empty locations&quot;">​</a></h2><p>A disconnected drive retains its index and cached derivatives, while healthy sources remain usable. Reconnect the drive and sync the same source to reuse its indexed records and saved state.</p><p>If a previously populated location appears completely empty, check the mount and sync again. Use <strong>Confirm empty location</strong> only after intentionally clearing the folder. Foldergram cannot reliably detect every filesystem replacement or disappearing nested mount.</p><p>Local and <a href="./immich">Immich connections</a> to the same files can produce duplicate posts. Choose one source for overlapping content, or use <a href="./configuration#excluded-folders">local folder exclusions</a> to skip the local copy.</p><h2 id="upgrading-an-existing-installation" tabindex="-1">Upgrading an existing installation <a class="header-anchor" href="#upgrading-an-existing-installation" aria-label="Permalink to &quot;Upgrading an existing installation&quot;">​</a></h2><p>Back up the SQLite database and application state before upgrading, including the Immich encryption key if used. Follow the <a href="./configuration#filesystem-and-backup-requirements">database backup guidance</a> to keep a consistent copy.</p><p>The upgrade assigns existing records to the primary gallery while preserving IDs, saved state, shares, and derivative paths. Deploy the updated server and client together. To roll back, restore the pre-upgrade backup with the matching older version.</p>`,24)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
